@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700;900&family=JetBrains+Mono:wght@400;500;700&display=swap');

:root {
  /* Cloudflare orange → red gradient */
  --cf-orange: #F38020;
  --cf-orange-light: #FAAE40;
  --cf-red: #FF5733;
  --cf-red-dark: #C73E1D;
  --cf-gradient: linear-gradient(135deg, #F38020, #FF5733);

  /* Pure black base */
  --enbu-bg: #000000;
  --enbu-surface: #0A0A0A;
  --enbu-surface-light: #1A1A1A;
  --enbu-border: #262626;

  /* White text */
  --enbu-text: #FFFFFF;
  --enbu-text-muted: #B3B3B3;
  --enbu-text-dim: #666666;

  /* Slidev overrides */
  --slidev-theme-primary: var(--cf-orange);
  --slidev-theme-accents-vulcan: var(--enbu-surface);
}

html.dark {
  color-scheme: dark;
}

/* Base typography */
.slidev-layout {
  font-family: 'Noto Sans JP', ui-sans-serif, system-ui, sans-serif;
  color: var(--enbu-text);
  background: var(--enbu-bg);
}

/* Headings */
.slidev-layout h1 {
  font-weight: 900;
  color: var(--enbu-text);
  letter-spacing: -0.02em;
}

.slidev-layout h2 {
  font-weight: 700;
  background: var(--cf-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.slidev-layout h3 {
  font-weight: 700;
  color: var(--cf-orange-light);
  font-size: 1.1em;
}

/* Paragraphs */
.slidev-layout p {
  color: var(--enbu-text);
  line-height: 1.7;
}

/* Strong / Bold */
.slidev-layout strong {
  color: var(--cf-orange);
  font-weight: 700;
}

/* Links */
.slidev-layout a {
  color: var(--cf-orange-light);
  text-decoration: none;
  border-bottom: 1px solid var(--cf-orange);
  transition: color 0.2s, border-color 0.2s;
}

.slidev-layout a:hover {
  color: var(--cf-red);
  border-color: var(--cf-red);
}

/* Blockquotes */
.slidev-layout blockquote {
  border-left: 3px solid var(--cf-red);
  background: var(--enbu-surface);
  padding: 0.75em 1.25em;
  border-radius: 0 6px 6px 0;
  color: var(--enbu-text-muted);
  font-style: normal;
}

.slidev-layout blockquote strong {
  color: var(--cf-orange);
}

/* Tables */
.slidev-layout table {
  border-collapse: collapse;
  width: 100%;
}

.slidev-layout th {
  background: var(--enbu-surface-light);
  color: var(--cf-orange);
  font-weight: 700;
  padding: 0.5em 0.75em;
  border-bottom: 2px solid var(--cf-red-dark);
  text-align: left;
}

.slidev-layout td {
  padding: 0.4em 0.75em;
  border-bottom: 1px solid var(--enbu-border);
  color: var(--enbu-text);
}

.slidev-layout tr:hover td {
  background: var(--enbu-surface);
}

/* Lists */
.slidev-layout ul {
  list-style: none;
  padding-left: 1.2em;
}

.slidev-layout ul > li::before {
  content: '▸';
  color: var(--cf-orange);
  font-weight: bold;
  margin-left: -1.2em;
  margin-right: 0.4em;
}

.slidev-layout ol {
  padding-left: 1.5em;
}

.slidev-layout ol > li::marker {
  color: var(--cf-orange);
  font-weight: 700;
}

/* Horizontal rule — Cloudflare gradient */
.slidev-layout hr {
  border: none;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--cf-red-dark),
    var(--cf-orange),
    var(--cf-orange-light),
    var(--cf-orange),
    var(--cf-red-dark),
    transparent
  );
  margin: 1.5em 0;
  opacity: 0.7;
}

/* Selection highlight */
.slidev-layout ::selection {
  background: var(--cf-orange);
  color: #000;
}

/* Slide number */
.slidev-page-number {
  color: var(--enbu-text-dim);
}

/* Progress bar */
.slidev-progress {
  background: var(--enbu-surface-light);
}

.slidev-progress > div {
  background: var(--cf-gradient);
}

/* Code blocks */
.slidev-layout code {
  color: var(--cf-orange-light);
  background: var(--enbu-surface);
  padding: 0.15em 0.4em;
  border-radius: 4px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 0.9em;
}

.slidev-layout pre code {
  background: transparent;
  padding: 0;
}

