    font-size: 1.1rem;
    font-weight: 400;
    letter-spacing: 0.4em;
    text-transform: uppercase;
    margin-top: 2.5rem;
    color: #fbad41;
    opacity: 0.75;
    text-shadow: 0 0 12px rgba(251, 173, 65, 0.4);
