    content: '';
    display: block;
    width: 60px;
    height: 1px;
    margin: 0 auto 1.5rem;
    background: linear-gradient(90deg, transparent, #fbad41, transparent);
    box-shadow: 0 0 8px rgba(251, 173, 65, 0.6);
}

