/* 流れ星: 細い光跡が斜めに走る。
   animation の duration を長く取り、発光〜消失は最初の 5-10% だけにすることで
   「たまに流れる」演出を実現。3 本を時差・角度・速度を変えて配置。 */
.shooting-star {
    position: absolute;
    width: 90px;
    height: 1.2px;
    background: linear-gradient(to right, transparent 0%, rgba(255, 255, 240, 0.9) 60%, rgba(255, 220, 180, 0.6) 90%, transparent 100%);
    border-radius: 1px;
    opacity: 0;
    pointer-events: none;
    will-change: transform, opacity;
}

.shooting-star-1 {
    top: 18%;
    left: -10%;
    transform: rotate(-18deg);
    animation: shoot 14s ease-out infinite;
}

.shooting-star-2 {
    top: 8%;
    left: 30%;
    transform: rotate(-22deg);
    width: 110px;
    animation: shoot 19s ease-out 6s infinite;
}

.shooting-star-3 {
    top: 32%;
    left: 55%;
    transform: rotate(-15deg);
    width: 75px;
    animation: shoot 23s ease-out 11s infinite;
}

@keyframes shoot {
    0%   { transform: rotate(var(--angle, -18deg)) translate3d(0, 0, 0);       opacity: 0; }
    2%   { opacity: 1; }
    8%   { transform: rotate(var(--angle, -18deg)) translate3d(420px, 130px, 0); opacity: 0; }
    100% { transform: rotate(var(--angle, -18deg)) translate3d(420px, 130px, 0); opacity: 0; }
}

